-- 테이블 sol.charge 구조 내보내기
CREATE TABLE IF NOT EXISTS `charge` (
  `charge_id` int(11) NOT NULL AUTO_INCREMENT,
  `users_id` int(11) NOT NULL,
  `charge_impuid` varchar(50) NOT NULL COMMENT '아임포트 결제 고유번호',
  `charge_merchant_uid` varchar(100) NOT NULL COMMENT '가맹점 주문번호',
  `charge_method` varchar(30) DEFAULT NULL COMMENT '결제수단',
  `charge_pg_provider` varchar(30) DEFAULT NULL COMMENT 'PG사',
  `charge_pg_tid` varchar(100) DEFAULT NULL COMMENT 'PG사 거래번호',
  `charge_receipt_url` varchar(500) DEFAULT NULL COMMENT '영수증 URL',
  `charge_status` varchar(20) NOT NULL COMMENT '결제 상태',
  `charge_status_detail` varchar(200) DEFAULT NULL COMMENT '결제 상태 상세',
  `charge_amount` int(11) NOT NULL COMMENT '충전 금액',
  `charge_cancel_amount` int(11) DEFAULT NULL COMMENT '환불 금액',
  `charge_buyer_name` varchar(50) DEFAULT NULL COMMENT '구매자 이름',
  `charge_buyer_email` varchar(100) DEFAULT NULL COMMENT '구매자 이메일',
  `charge_buyer_tel` varchar(20) DEFAULT NULL COMMENT '구매자 연락처',
  `charge_fail_reason` varchar(300) DEFAULT NULL COMMENT '결제 실패 사유',
  `charge_cancel_reason` varchar(300) DEFAULT NULL COMMENT '결제 취소/환불 사유',
  `charge_paid_at` datetime DEFAULT NULL COMMENT '결제 일시',
  `charge_cancelled_at` datetime DEFAULT NULL COMMENT '환불 일시',
  `charge_created_at` datetime DEFAULT current_timestamp() COMMENT '레코드 생성일시',
  `charge_updated_at` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp() COMMENT '레코드 수정일시',
  PRIMARY KEY (`charge_id`),
  UNIQUE KEY `idx_charge_impuid` (`charge_impuid`),
  KEY `idx_charge_merchant_uid` (`charge_merchant_uid`),
  KEY `idx_charge_status` (`charge_status`),
  KEY `idx_charge_paid_at` (`charge_paid_at`),
  KEY `idx_charge_users_id` (`users_id`)
) ENGINE=InnoDB AUTO_INCREMENT=12 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_uca1400_ai_ci;

