-- 테이블 sol.integrated_payment 구조 내보내기
CREATE TABLE IF NOT EXISTS `integrated_payment` (
  `integratedpayment_id` int(11) NOT NULL AUTO_INCREMENT COMMENT '통합 결제 PK',
  `store_id` int(11) NOT NULL COMMENT '매장 ID (FK)',
  `integratedpayment_leader_id` int(11) NOT NULL COMMENT '결제 발의자 ID (FK)',
  `integratedpayment_amount` int(11) NOT NULL COMMENT '총 결제 금액',
  `integratedpayment_people` int(11) NOT NULL DEFAULT 1 COMMENT '총 결제 인원',
  `integratedpayment_status` varchar(20) NOT NULL DEFAULT 'pending' COMMENT '총 결제 상태 (pending: 대기, processing: 진행중, completed: 완료, cancelled: 취소)',
  `integratedpayment_created_at` timestamp NULL DEFAULT current_timestamp() COMMENT '생성일시',
  `integratedpayment_updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp() COMMENT '수정일시',
  PRIMARY KEY (`integratedpayment_id`),
  KEY `idx_store_id` (`store_id`),
  KEY `idx_leader_id` (`integratedpayment_leader_id`),
  KEY `idx_status` (`integratedpayment_status`),
  KEY `idx_created_at` (`integratedpayment_created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=161 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='통합 결제 정보 테이블';

