-- 테이블 sol.payment 구조 내보내기
CREATE TABLE IF NOT EXISTS `payment` (
  `payment_id` int(11) NOT NULL AUTO_INCREMENT COMMENT '결제 PK',
  `users_id` int(11) NOT NULL COMMENT '유저 ID',
  `integratedpayment_id` int(11) NOT NULL COMMENT '통합 결제 ID',
  `payment_used_point` int(11) DEFAULT NULL COMMENT '결제 시 사용한 포인트',
  `payment_paid_amount` int(11) DEFAULT NULL COMMENT '결제 시 결제한 금액',
  `payment_impuid` varchar(50) DEFAULT NULL COMMENT '아임포트 결제 고유번호',
  `payment_merchant_uid` varchar(100) DEFAULT NULL COMMENT '가맹점 주문번호',
  `payment_method` varchar(30) DEFAULT NULL COMMENT '결제수단(card, trans, vbank 등)',
  `payment_pg_provider` varchar(30) DEFAULT NULL COMMENT 'PG사(html5_inicis, kcp 등)',
  `payment_pg_tid` varchar(100) DEFAULT NULL COMMENT 'PG사 거래번호',
  `payment_receipt_url` varchar(500) DEFAULT NULL COMMENT '영수증 URL',
  `payment_status` varchar(20) NOT NULL DEFAULT 'pending' COMMENT '결제 상태(pending/paid/failed/cancelled/refunded)',
  `payment_status_detail` varchar(200) DEFAULT NULL COMMENT '결제 상태 상세(실패/취소/환불 등 상세 사유)',
  `payment_amount` int(11) NOT NULL COMMENT '결제/충전 금액',
  `payment_cancel_amount` int(11) DEFAULT 0 COMMENT '환불 금액',
  `payment_buyer_name` varchar(50) DEFAULT NULL COMMENT '구매자 이름',
  `payment_buyer_email` varchar(100) DEFAULT NULL COMMENT '구매자 이메일',
  `payment_buyer_tel` varchar(20) DEFAULT NULL COMMENT '구매자 연락처',
  `payment_fail_reason` varchar(300) DEFAULT NULL COMMENT '결제 실패 사유',
  `payment_cancel_reason` varchar(300) DEFAULT NULL COMMENT '결제 취소/환불 사유',
  `payment_paid_at` timestamp NULL DEFAULT NULL COMMENT '결제 일시',
  `payment_cancelled_at` timestamp NULL DEFAULT NULL COMMENT '환불 일시',
  `payment_created_at` timestamp NULL DEFAULT current_timestamp() COMMENT '레코드 생성일시',
  `payment_updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp() COMMENT '레코드 수정일시',
  PRIMARY KEY (`payment_id`),
  UNIQUE KEY `payment_merchant_uid` (`payment_merchant_uid`),
  UNIQUE KEY `payment_impuid` (`payment_impuid`),
  KEY `idx_payment_merchant_uid` (`payment_merchant_uid`),
  KEY `idx_payment_impuid` (`payment_impuid`),
  KEY `idx_payment_status` (`payment_status`),
  KEY `idx_payment_created_at` (`payment_created_at`),
  KEY `idx_store_id` (`users_id`) USING BTREE,
  KEY `idx_payment_leader_id` (`integratedpayment_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=359 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='결제 정보 테이블';

