	(260, 323, '흑당버블밀크티라떼', 4700, 'https://sol-food-bucket.s3.ap-northeast-2.amazonaws.com/profiles/10d2c6cb-9ad9-41ba-b911-30d39d9832c6.profile_1751960050687.jpg', '타바론 얼그레이 홍차의 깊은 맛을 살린 일크티 라떼에 진한 흑당과 흑당 버블의 달콤함을 채운 음료.', '[]'),
	(261, 323, '오레오초코라떼', 4600, 'https://sol-food-bucket.s3.ap-northeast-2.amazonaws.com/profiles/3618cacc-1673-4eea-b794-1d12841d084f.profile_1751960131658.jpg', '진한 초코와 리얼 오레오를 블렌딩해 씹는 맛을 더한 달콤한 아이스 라떼.', '[]'),
	(262, 323, '디카페인 헤이즐넛 라떼', 3900, 'https://sol-food-bucket.s3.ap-northeast-2.amazonaws.com/profiles/877e4468-03de-4955-9782-35845ba4d829.profile_1751960248706.jpg', '부드러운 카페라떼에 헤이즐넛의 풍부한 향과 달콤함을 담아 향긋하게 즐길 수 있는 디카페인 라떼', '[]'),
	(263, 323, '딸기쿠키프라페', 5200, 'https://sol-food-bucket.s3.ap-northeast-2.amazonaws.com/profiles/593f0d01-8c44-4654-9e7a-b2b58b69da82.profile_1751960290384.jpg', '부드러운 바닐라와 달달한 딸기, 바삭한 오레오 쿠키가 달콤한 하모니를 선물하는 프라페', '[]'),
	(264, 323, '플레인크로플', 2300, 'https://sol-food-bucket.s3.ap-northeast-2.amazonaws.com/profiles/21009ea3-4fc0-4a37-a782-0e135c9c62cd.profile_1751960333897.jpg', '버터풍미가 가득한 크루와상의 바삭함과 와플의 부드러움을 합친 겉바속촉 베이커리 메뉴', '[]'),
	(265, 323, '버터버터 팥슈크림 페스츄리', 3200, 'https://sol-food-bucket.s3.ap-northeast-2.amazonaws.com/profiles/815bbaf0-6875-44b2-98a9-a676c1b14a7e.profile_1751960376747.jpg', '버터의 풍미가 가득 바삭한 페스츄리 사이에 팥앙금과 슈크림을 가득 넣어 두 가지 맛을 반반 즐길 수 있는 페스츄리', '[]'),
	(266, 323, '팥빙 초코 젤라또 파르페', 6400, 'https://sol-food-bucket.s3.ap-northeast-2.amazonaws.com/profiles/7d2d2c68-ef7a-48d9-b87a-790466a74d43.profile_1751960414527.jpg', '기존 팥젤라또를 초코젤라또로 변경한 팥빙 초코젤라또 파르페', '[]'),
	(267, 321, 'test', 100, '', 'for test', ''),
	(268, 5, '아메리카노', 4500, 'https://sol-food-bucket.s3.ap-northeast-2.amazonaws.com/storeImg/americano.jpg', '깊고 진한 에스프레소와 물의 조화로 완성된 클래식한 아메리카노', '[]'),
	(269, 5, '카페라떼', 5000, 'https://sol-food-bucket.s3.ap-northeast-2.amazonaws.com/storeImg/caffemoka.jpg', '부드러운 우유와 에스프레소가 만나 완성된 부드러운 카페라떼', '[{"groupName":"사이즈","required":false,"maxSelect":1,"options":[{"name":"톨","price":0},{"name":"그란데","price":500},{"name":"벤티","price":1000}]}]'),
	(270, 5, '카푸치노', 5000, 'https://sol-food-bucket.s3.ap-northeast-2.amazonaws.com/storeImg/%5B38%5D_20210415154821991.jpg', '에스프레소와 스팀밀크, 우유 거품의 완벽한 비율로 완성된 카푸치노', '[{"groupName":"사이즈","required":false,"maxSelect":1,"options":[{"name":"톨","price":0},{"name":"그란데","price":500},{"name":"벤티","price":1000}]}]'),
	(271, 5, '카라멜 마끼아또', 5500, 'https://sol-food-bucket.s3.ap-northeast-2.amazonaws.com/storeImg/makiyato.jpg', '달콤한 카라멜 시럽과 부드러운 우유, 에스프레소가 어우러진 카라멜 마끼아또', '[{"groupName":"사이즈","required":false,"maxSelect":1,"options":[{"name":"톨","price":0},{"name":"그란데","price":500},{"name":"벤티","price":1000}]},{"groupName":"시럽","required":false,"maxSelect":1,"options":[{"name":"카라멜 시럽 추가","price":300},{"name":"바닐라 시럽 추가","price":300}]}]'),
	(272, 5, '카페모카', 5500, 'https://sol-food-bucket.s3.ap-northeast-2.amazonaws.com/storeImg/caffemoka.jpg', '진한 에스프레소와 달콤한 모카 시럽, 부드러운 우유가 만나 완성된 모카', '[{"groupName":"사이즈","required":false,"maxSelect":1,"options":[{"name":"톨","price":0},{"name":"그란데","price":500},{"name":"벤티","price":1000}]}]'),
	(273, 5, '바닐라 라떼', 5500, 'https://sol-food-bucket.s3.ap-northeast-2.amazonaws.com/storeImg/%5B38%5D_20210415154821991.jpg', '달콤한 바닐라 시럽과 부드러운 우유, 에스프레소의 조화로운 바닐라 라떼', '[{"groupName":"사이즈","required":false,"maxSelect":1,"options":[{"name":"톨","price":0},{"name":"그란데","price":500},{"name":"벤티","price":1000}]}]'),
	(274, 5, '돌체 라떼', 5500, 'https://sol-food-bucket.s3.ap-northeast-2.amazonaws.com/storeImg/dolche.jpg', '달콤한 돌체 시럽과 부드러운 우유, 에스프레소가 어우러진 돌체 라떼', '[{"groupName":"사이즈","required":false,"maxSelect":1,"options":[{"name":"톨","price":0},{"name":"그란데","price":500},{"name":"벤티","price":1000}]}]'),
	(275, 5, '화이트 초콜릿 모카', 6000, 'https://sol-food-bucket.s3.ap-northeast-2.amazonaws.com/storeImg/whitechmoka.jpg', '달콤한 화이트 초콜릿과 부드러운 우유, 에스프레소의 조화로운 화이트 초콜릿 모카', '[{"groupName":"사이즈","required":false,"maxSelect":1,"options":[{"name":"톨","price":0},{"name":"그란데","price":500},{"name":"벤티","price":1000}]}]'),
	(276, 5, '에스프레소', 3500, 'https://sol-food-bucket.s3.ap-northeast-2.amazonaws.com/storeImg/esspreso.jpg', '스타벅스의 핵심, 깊고 진한 에스프레소의 본연의 맛', '[]'),
	(277, 5, '콜드브루', 5500, 'https://sol-food-bucket.s3.ap-northeast-2.amazonaws.com/storeImg/coldbrou.jpg', '20시간 저온 추출로 완성된 부드럽고 깊은 맛의 콜드브루', '[{"groupName":"사이즈","required":false,"maxSelect":1,"options":[{"name":"톨","price":0},{"name":"그란데","price":500},{"name":"벤티","price":1000}]}]'),
	(278, 15, '와퍼', 6500, 'https://sol-food-bucket.s3.ap-northeast-2.amazonaws.com/storeImg/waper.png', '불맛 가득한 직화구이 패티와 신선한 야채가 어우러진 버거킹의 대표 메뉴', '[{"groupName":"사이즈","required":false,"maxSelect":1,"options":[{"name":"단품","price":0},{"name":"세트","price":2000}]}]'),
