	(281, 15, '치킨킹', 5500, 'https://sol-food-bucket.s3.ap-northeast-2.amazonaws.com/storeImg/chickenking.png', '바삭한 치킨 패티와 신선한 야채가 어우러진 치킨킹', '[{"groupName":"사이즈","required":false,"maxSelect":1,"options":[{"name":"단품","price":0},{"name":"세트","price":2000}]}]'),
	(282, 15, '치킨킹 더블', 6500, 'https://sol-food-bucket.s3.ap-northeast-2.amazonaws.com/storeImg/b24d04e3-96d6-4cc1-b07d-fc171a7fc6b8.png', '두 장의 바삭한 치킨 패티로 더욱 든든한 치킨킹 더블', '[{"groupName":"사이즈","required":false,"maxSelect":1,"options":[{"name":"단품","price":0},{"name":"세트","price":2000}]}]'),
